package indexroom

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync/atomic"
)

// ErrInvalidArgument marks a rejected query: out-of-range heights or page
// size, a malformed cursor, a cursor issued by another index instance, or
// continuation conditions that differ from the first page. It never reports
// chain data problems; use errors.Is to tell it apart from ErrQueryChanged.
var ErrInvalidArgument = errors.New("indexroom: invalid query argument")

// ErrQueryChanged marks a continuation whose pinned range no longer matches
// the first page: a block in the range was replaced (even under the same
// hash, and even if only its timestamp changed) or the chain was shortened
// below the pinned upper bound. No results are returned; the caller must
// restart from a first-page query.
var ErrQueryChanged = errors.New("indexroom: query data changed")

// queryTxsHookLocked is a test-only rendezvous invoked once per QueryTxs
// call while index.mu is held: for a first page after the tip-bound height has
// been resolved (and non-empty ranges only), and for a continuation only after
// every pinned-range check has passed, so the call is committed to a
// successful page against the chain state in effect. It is nil in production;
// reorg regression tests park a query here to force a concurrent Reorg to wait
// (or park the Reorg and make the query wait), making the "one complete
// main-chain view per page" observation deterministic instead of relying on
// scheduling luck.
var queryTxsHookLocked func(from, to int64, continuation bool)

const (
	// DefaultPageSize is the page length when TxQuery.PageSize is zero.
	DefaultPageSize = 100
	// MaxPageSize is the largest accepted TxQuery.PageSize.
	MaxPageSize = 1000
)

// TxOrder selects the occurrence order of a QueryTxs result.
type TxOrder int

const (
	// OrderAsc returns occurrences by increasing height and, inside one
	// block, by increasing position. It is the zero value.
	OrderAsc TxOrder = 0
	// OrderDesc returns occurrences by decreasing height and, inside one
	// block, by decreasing position. The order is decided by height and the
	// original block positions alone; block timestamps never participate.
	OrderDesc TxOrder = 1
)

func (order TxOrder) valid() bool {
	return order == OrderAsc || order == OrderDesc
}

// TxQuery describes a transaction lookup against the main chain.
type TxQuery struct {
	// From and To bound the searched heights, both inclusive. A zero From
	// starts at height 1. A zero To pins the chain tip seen by the first
	// page; an explicit To above the tip is clamped to it. Explicit heights
	// must be positive, and an explicit To must not be below From.
	From int64
	To   int64
	// TxIDs restricts results to these identifiers, matched by exact string
	// comparison; an empty slice disables the filter. Duplicates and order
	// inside the slice are irrelevant.
	TxIDs []string
	// PageSize picks the page length, 1..MaxPageSize; zero means
	// DefaultPageSize. It may change between pages of the same query.
	PageSize int
	// Order selects the occurrence order over the whole pinned range:
	// OrderAsc (the zero value) by increasing height/position, OrderDesc by
	// decreasing height/position. A continuation must repeat the first
	// page's order, otherwise QueryTxs returns ErrInvalidArgument.
	Order TxOrder
	// TimeStart and TimeEnd optionally bound the searched block timestamps as
	// a half-open window [TimeStart, TimeEnd), reusing QueryTimeStats
	// semantics: non-negative Unix seconds, start included, end excluded.
	// Both pointers nil disables time filtering, so an unused window stays
	// distinct from a window whose start is genuinely zero; providing exactly
	// one bound is ErrInvalidArgument. While enabled, a block without a
	// timestamp never matches, while a real timestamp of zero is judged like
	// any other value. The filter only selects which occurrences survive:
	// ordering still depends solely on height and block position. A
	// continuation must repeat whether the filter is enabled and the exact
	// same window, otherwise QueryTxs returns ErrInvalidArgument.
	TimeStart *int64
	TimeEnd   *int64
	// MinBlocks optionally requires a transaction identifier to appear in at
	// least this many distinct blocks of the pinned range before any of its
	// occurrences are kept. Zero (the default) disables the filter; a
	// negative value is ErrInvalidArgument. Block membership is counted over
	// the whole pinned height range under the same TxIDs and time-window
	// conditions as the scan itself: repeated occurrences inside one block
	// count once, and blocks outside the range, without a timestamp, or
	// outside the window never help an identifier qualify. Qualification is
	// decided by the entire pinned range, never by the current page alone;
	// once an identifier qualifies, every one of its matching occurrences is
	// kept, with no deduplication. A continuation must repeat the first
	// page's value, otherwise QueryTxs returns ErrInvalidArgument.
	MinBlocks int64
	// Cursor continues an earlier query; empty asks for the first page. On
	// continuation the height range, TxIDs, Order, time window and MinBlocks
	// must equal the first page's.
	Cursor string
}

// TxHit is one transaction occurrence on the main chain. The same
// identifier appears once per occurrence, in different blocks or several
// times inside one block.
type TxHit struct {
	Height    int64
	BlockHash string
	TxID      string
	Position  int
}

// TxPage is one page of query results together with statistics over the
// whole filtered range. Hits are ordered by height then position inside the
// block: both increasing under OrderAsc and both decreasing under OrderDesc.
// A hit's Position stays its zero-based index inside the block; descending
// order never renumbers it.
type TxPage struct {
	Hits []TxHit
	// TotalMatches counts every matching occurrence in the pinned range; it
	// does not change between pages of the same query.
	TotalMatches int64
	// MatchedBlocks counts the blocks holding at least one match.
	MatchedBlocks int64
	// ToHeight is the upper bound pinned by the first page: the requested
	// To clamped to the chain tip seen at that moment.
	ToHeight int64
	// NextCursor continues the query; empty means this is the last page.
	NextCursor string
}

// QueryTxs searches the main chain for transaction occurrences matching the
// query. Every call observes one complete chain state: concurrent Append or
// Reorg calls never leak into a page, and the returned records are copies
// the caller may freely mutate. The query itself never modifies the index.
//
// With Order OrderAsc (the zero value) hits arrive by increasing height and
// position inside the block; OrderDesc walks the same pinned range the other
// way, from the tip-bound upper height downward, positions inside each block
// likewise decreasing. Ordering depends only on height and position — never
// on block timestamps — and ascending queries behave exactly as before.
//
// TimeStart and TimeEnd together enable an optional timestamp window
// [TimeStart, TimeEnd) with the same semantics as QueryTimeStats: it
// intersects the height range and the TxIDs filter rather than replacing
// them, timestamps need not be monotonic, a missing timestamp never
// matches, and a real zero is judged normally. Time filtering never changes
// the order, the block positions, or the deduplication of occurrences.
//
// MinBlocks optionally keeps only the identifiers appearing in at least
// that many distinct blocks of the pinned range, counted under the same
// TxIDs and time-window conditions. Qualification is decided over the whole
// pinned range before paging, so every page reports the same TotalMatches
// and MatchedBlocks, and a qualifying identifier keeps all of its matching
// occurrences in their original order and positions.
//
// The first page (empty Cursor) pins the filtered range and returns a
// continuation cursor while more results remain. Continuations reuse the
// pinned range — blocks appended above it are invisible to the query — and
// succeed as long as every block inside the range still matches the first
// page; otherwise they fail with ErrQueryChanged. The order, the time
// filter's enabled state and its window are pinned too: a cursor minted in
// one direction or with one window may not be continued with another.
func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
	pageSize, err := normalizePageSize(query.PageSize)
	if err != nil {
		return TxPage{}, err
	}
	if !query.Order.valid() {
		return TxPage{}, fmt.Errorf("%w: order must be OrderAsc or OrderDesc", ErrInvalidArgument)
	}
	window, err := normalizeTimeWindow(query.TimeStart, query.TimeEnd)
	if err != nil {
		return TxPage{}, err
	}
	if query.MinBlocks < 0 {
		return TxPage{}, fmt.Errorf("%w: min blocks must not be negative", ErrInvalidArgument)
	}
	if query.Cursor != "" {
		return index.continueQuery(query, pageSize, window)
	}
	return index.firstQuery(query, pageSize, window)
}

// timeWindow is the canonical form of TxQuery's optional timestamp window.
// enabled is false only when both bounds are absent, so an unused window
// stays distinct from [0, end); when enabled, start and end hold non-negative
// Unix seconds with start < end.
type timeWindow struct {
	enabled bool
	start   int64
	end     int64
}

// normalizeTimeWindow validates the optional half-open window: both bounds
// must be absent together, neither may be negative, and the start must be
// below the end. Exactly one bound, a negative bound, or a non-empty window
// of zero or negative width is ErrInvalidArgument.
func normalizeTimeWindow(startPtr, endPtr *int64) (timeWindow, error) {
	if (startPtr == nil) != (endPtr == nil) {
		return timeWindow{}, fmt.Errorf("%w: time window needs both start and end or neither", ErrInvalidArgument)
	}
	if startPtr == nil {
		return timeWindow{}, nil
	}
	if *startPtr < 0 {
		return timeWindow{}, fmt.Errorf("%w: time window start must not be negative", ErrInvalidArgument)
	}
	if *endPtr < 0 {
		return timeWindow{}, fmt.Errorf("%w: time window end must not be negative", ErrInvalidArgument)
	}
	if *startPtr >= *endPtr {
		return timeWindow{}, fmt.Errorf("%w: time window start must be below end", ErrInvalidArgument)
	}
	return timeWindow{enabled: true, start: *startPtr, end: *endPtr}, nil
}

// contains reports whether a block timestamp survives the window: an
// enabled window rejects missing timestamps, while start is included and end
// excluded. A disabled window matches regardless of the timestamp.
func (w timeWindow) contains(when *int64) bool {
	if !w.enabled {
		return true
	}
	if when == nil {
		return false
	}
	return *when >= w.start && *when < w.end
}

func normalizePageSize(size int) (int, error) {
	if size == 0 {
		return DefaultPageSize, nil
	}
	if size < 0 || size > MaxPageSize {
		return 0, fmt.Errorf("%w: page size must be between 1 and %d", ErrInvalidArgument, MaxPageSize)
	}
	return size, nil
}

// normalizeRange validates the requested heights and resolves the zero From
// default. A zero To is left as-is; it is resolved against the chain tip
// while holding the lock.
func normalizeRange(from, to int64) (int64, int64, error) {
	if from < 0 {
		return 0, 0, fmt.Errorf("%w: from height must be positive", ErrInvalidArgument)
	}
	if to < 0 {
		return 0, 0, fmt.Errorf("%w: to height must be positive", ErrInvalidArgument)
	}
	if from == 0 {
		from = 1
	}
	if to != 0 && to < from {
		return 0, 0, fmt.Errorf("%w: to height is below from height", ErrInvalidArgument)
	}
	return from, to, nil
}

func (index *Index) firstQuery(query TxQuery, pageSize int, window timeWindow) (TxPage, error) {
	from, to, err := normalizeRange(query.From, query.To)
	if err != nil {
		return TxPage{}, err
	}

	index.mu.Lock()
	defer index.mu.Unlock()

	if to == 0 || to > index.Tip {
		to = index.Tip
	}
	page := TxPage{Hits: []TxHit{}, ToHeight: to}
	if from > to {
		// Empty index or a start above the tip: a successful empty result.
		return page, nil
	}
	if queryTxsHookLocked != nil {
		queryTxsHookLocked(from, to, false)
	}
	filter := newTxFilter(query.TxIDs)
	qualified := index.qualifyingIDsLocked(from, to, filter, window, query.MinBlocks)
	hits, total, blocks := index.scanPageQualifiedLocked(from, to, filter, window, query.Order, 0, pageSize, qualified)
	return index.buildPageLocked(query.To, filter, window, from, to, hits, total, blocks, 0, pageSize, query.Order, query.MinBlocks), nil
}

func (index *Index) continueQuery(query TxQuery, pageSize int, window timeWindow) (TxPage, error) {
	payload, err := index.decodeCursor(query.Cursor)
	if err != nil {
		return TxPage{}, err
	}
	from, _, err := normalizeRange(query.From, query.To)
	if err != nil {
		return TxPage{}, err
	}
	if from != payload.From {
		return TxPage{}, fmt.Errorf("%w: from height differs from the first page", ErrInvalidArgument)
	}
	if query.To != payload.ReqTo {
		return TxPage{}, fmt.Errorf("%w: to height differs from the first page", ErrInvalidArgument)
	}
	// One canonicalization drives both set-equivalence and the rescanning
	// filter; reordering or repeating identifiers changes nothing, while any
	// added, removed, or replaced identifier rejects the continuation before
	// the chain is examined.
	filter := newTxFilter(query.TxIDs)
	if filter.hexDigest() != payload.Set {
		return TxPage{}, fmt.Errorf("%w: transaction filter differs from the first page", ErrInvalidArgument)
	}
	if query.Order != payload.Order {
		return TxPage{}, fmt.Errorf("%w: read order differs from the first page", ErrInvalidArgument)
	}
	// The time window is pinned like the other conditions: enabling it on a
	// cursor minted without one (or the reverse), or shifting either bound,
	// rejects the continuation before the chain is examined. The caller must
	// restart from an empty cursor.
	if window != payload.window() {
		return TxPage{}, fmt.Errorf("%w: time window differs from the first page", ErrInvalidArgument)
	}
	// MinBlocks is pinned like the other conditions: a cursor minted with
	// one threshold may not be continued with another.
	if query.MinBlocks != payload.MinBlocks {
		return TxPage{}, fmt.Errorf("%w: min blocks differs from the first page", ErrInvalidArgument)
	}

	index.mu.Lock()
	defer index.mu.Unlock()

	if index.Tip < payload.To {
		return TxPage{}, fmt.Errorf("%w: chain tip %d is below the pinned upper bound %d",
			ErrQueryChanged, index.Tip, payload.To)
	}
	if got := hex.EncodeToString(index.fingerprintLocked(payload.From, payload.To)); got != payload.FP {
		return TxPage{}, fmt.Errorf("%w: blocks in the pinned range differ from the first page", ErrQueryChanged)
	}
	if queryTxsHookLocked != nil {
		queryTxsHookLocked(payload.From, payload.To, true)
	}
	// Re-scan the still-identical pinned range: the cursor records the
	// absolute offset, but no full match list is kept between pages.
	qualified := index.qualifyingIDsLocked(payload.From, payload.To, filter, window, payload.MinBlocks)
	hits, total, blocks := index.scanPageQualifiedLocked(payload.From, payload.To, filter, window, payload.Order, payload.Off, pageSize, qualified)
	if payload.Off > total {
		return TxPage{}, fmt.Errorf("%w: cursor offset is beyond the pinned results", ErrQueryChanged)
	}
	return index.buildPageLocked(query.To, filter, window, payload.From, payload.To, hits, total, blocks, payload.Off, pageSize, payload.Order, payload.MinBlocks), nil
}

// buildPageLocked assembles one page from a page-sized scan and mints the
// continuation cursor when matches remain. total and blocks describe the
// whole pinned range; hits holds only the window [offset, offset+pageSize)
// in the scan's order. reqTo is the caller's verbatim To (zero for
// tip-bound queries). The caller must hold index.mu.
func (index *Index) buildPageLocked(reqTo int64, filter txFilter, window timeWindow, from, to int64, hits []TxHit, total, blocks, offset int64, pageSize int, order TxOrder, minBlocks int64) TxPage {
	page := TxPage{
		Hits:          hits,
		TotalMatches:  total,
		MatchedBlocks: blocks,
		ToHeight:      to,
	}
	if offset+int64(len(hits)) < total {
		payload := cursorPayload{
			V:         1,
			From:      from,
			ReqTo:     reqTo,
			To:        to,
			Set:       filter.hexDigest(),
			FP:        hex.EncodeToString(index.fingerprintLocked(from, to)),
			Order:     order,
			Off:       offset + int64(len(hits)),
			MinBlocks: minBlocks,
		}
		if window.enabled {
			start, end := window.start, window.end
			payload.TimeStart, payload.TimeEnd = &start, &end
		}
		page.NextCursor = index.encodeCursor(payload)
	}
	return page
}

// qualifyingIDsLocked applies the MinBlocks condition: it counts, for every
// identifier passing the filter, the distinct blocks of [from, to] that hold
// it and also survive the timestamp window, then keeps the identifiers
// reaching minBlocks. Blocks outside the window (or without a timestamp
// while the window is enabled) contribute nothing. A nil map is returned
// when minBlocks is zero, meaning every occurrence passes; an empty non-nil
// map means the filter is active and nothing qualified. The caller must hold
// index.mu.
func (index *Index) qualifyingIDsLocked(from, to int64, filter txFilter, window timeWindow, minBlocks int64) map[string]struct{} {
	if minBlocks <= 0 {
		return nil
	}
	counts := make(map[string]int64)
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		if !window.contains(block.Time) {
			continue
		}
		// One block contributes at most one to an identifier's count, however
		// many times the identifier repeats inside it.
		seen := make(map[string]struct{}, len(block.Txs))
		for _, tx := range block.Txs {
			if !filter.matches(tx) {
				continue
			}
			if _, ok := seen[tx]; ok {
				continue
			}
			seen[tx] = struct{}{}
			counts[tx]++
		}
	}
	qualified := make(map[string]struct{}, len(counts))
	for id, n := range counts {
		if n >= minBlocks {
			qualified[id] = struct{}{}
		}
	}
	return qualified
}

// scanPageLocked is scanPageQualifiedLocked without a MinBlocks condition:
// every occurrence passing the identifier filter and the time window counts.
func (index *Index) scanPageLocked(from, to int64, filter txFilter, window timeWindow, order TxOrder, offset int64, pageSize int) (hits []TxHit, total, blocks int64) {
	return index.scanPageQualifiedLocked(from, to, filter, window, order, offset, pageSize, nil)
}

// scanPageQualifiedLocked walks the whole pinned range once in the requested
// order, counting every matching occurrence and every block holding one,
// while retaining only the page window [offset, offset+pageSize) in a
// pre-sized slice: at most pageSize TxHit records, independent of how many
// matches the whole range holds. OrderAsc walks increasing heights then
// increasing positions; OrderDesc walks decreasing heights then decreasing
// positions. total, blocks and the recorded positions are the same in either
// order. An occurrence survives only when it passes the identifier filter,
// the block's timestamp window, and — when qualified is non-nil — its
// identifier belongs to the MinBlocks-qualified set computed over the whole
// pinned range; qualifying occurrences are kept individually, never
// deduplicated. The window never participates in ordering. The caller must
// hold index.mu.
func (index *Index) scanPageQualifiedLocked(from, to int64, filter txFilter, window timeWindow, order TxOrder, offset int64, pageSize int, qualified map[string]struct{}) (hits []TxHit, total, blocks int64) {
	hits = make([]TxHit, 0, pageSize)
	height, step := from, int64(1)
	if order == OrderDesc {
		height, step = to, -1
	}
	for ; from <= height && height <= to; height += step {
		block := index.Blocks[height]
		if !window.contains(block.Time) {
			// A block outside the timestamp window contributes no
			// occurrences, whatever transactions it holds.
			continue
		}
		matched := false
		position, pStep := 0, 1
		end := len(block.Txs)
		if order == OrderDesc {
			position, pStep, end = len(block.Txs)-1, -1, -1
		}
		for ; position != end; position += pStep {
			tx := block.Txs[position]
			if !filter.matches(tx) {
				continue
			}
			if qualified != nil {
				if _, ok := qualified[tx]; !ok {
					continue
				}
			}
			if total >= offset && int64(len(hits)) < int64(pageSize) {
				hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
			}
			total++
			matched = true
		}
		if matched {
			blocks++
		}
	}
	return hits, total, blocks
}

// fingerprintLocked hashes the exact content of every block in [from, to]:
// height, hash, parent, the ordered transaction list, and the timestamp
// (distinguishing a missing timestamp from zero). The caller must hold
// index.mu.
func (index *Index) fingerprintLocked(from, to int64) []byte {
	h := sha256.New()
	var lenBuf [8]byte
	writeString := func(s string) {
		binary.BigEndian.PutUint64(lenBuf[:], uint64(len(s)))
		h.Write(lenBuf[:])
		h.Write([]byte(s))
	}
	for height := from; height <= to; height++ {
		block := index.Blocks[height]
		binary.BigEndian.PutUint64(lenBuf[:], uint64(block.Height))
		h.Write(lenBuf[:])
		writeString(block.Hash)
		writeString(block.Parent)
		binary.BigEndian.PutUint64(lenBuf[:], uint64(len(block.Txs)))
		h.Write(lenBuf[:])
		for _, tx := range block.Txs {
			writeString(tx)
		}
		if block.Time == nil {
			h.Write([]byte{0})
		} else {
			h.Write([]byte{1})
			binary.BigEndian.PutUint64(lenBuf[:], uint64(*block.Time))
			h.Write(lenBuf[:])
		}
	}
	return h.Sum(nil)
}

// cursorPayload is the signed state carried between pages of one query.
//
// TimeStart and TimeEnd are both absent for a query without a timestamp
// window and both present for one with one, mirroring TxQuery; a window
// starting at zero still carries an explicit zero pointer, so it can never
// be confused with the disabled case.
type cursorPayload struct {
	V     int     `json:"v"`
	From  int64   `json:"from"`
	ReqTo int64   `json:"reqTo"`
	To    int64   `json:"to"`
	Set   string  `json:"set"`
	FP    string  `json:"fp"`
	Order TxOrder `json:"ord"`
	Off   int64   `json:"off"`
	// MinBlocks carries the first page's threshold; omitted when zero so
	// cursors minted before the field existed keep validating.
	MinBlocks int64  `json:"minB,omitempty"`
	TimeStart *int64 `json:"tStart,omitempty"`
	TimeEnd   *int64 `json:"tEnd,omitempty"`
}

// window reconstructs the pinned timestamp window. A signed payload is only
// ever minted by buildPageLocked with both pointers present together;
// malformed combinations fail closed as a disabled-window mismatch rather
// than panicking.
func (p cursorPayload) window() timeWindow {
	if p.TimeStart == nil || p.TimeEnd == nil {
		return timeWindow{}
	}
	return timeWindow{enabled: true, start: *p.TimeStart, end: *p.TimeEnd}
}

const cursorPrefix = "q1"

// encodeCursor serializes the payload and signs it with the per-instance
// key, so cursors are self-contained yet unusable on any other index.
func (index *Index) encodeCursor(payload cursorPayload) string {
	raw, err := json.Marshal(payload)
	if err != nil {
		panic(err) // cursorPayload only contains marshalable fields
	}
	body := base64.RawURLEncoding.EncodeToString(raw)
	mac := hmac.New(sha256.New, index.key[:])
	mac.Write([]byte(cursorPrefix + "." + body))
	sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	return cursorPrefix + "." + body + "." + sig
}

// decodeCursor verifies the signature before trusting any payload field;
// every failure is an argument error, never a data-changed error.
func (index *Index) decodeCursor(cursor string) (cursorPayload, error) {
	var payload cursorPayload
	parts := strings.Split(cursor, ".")
	if len(parts) != 3 || parts[0] != cursorPrefix {
		return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
	}
	sig, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil {
		return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
	}
	mac := hmac.New(sha256.New, index.key[:])
	mac.Write([]byte(parts[0] + "." + parts[1]))
	if !hmac.Equal(sig, mac.Sum(nil)) {
		return payload, fmt.Errorf("%w: cursor not recognized by this index", ErrInvalidArgument)
	}
	raw, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
	}
	if err := json.Unmarshal(raw, &payload); err != nil || payload.V != 1 {
		return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
	}
	return payload, nil
}

var keyFallback atomic.Uint64

// newKey derives the per-instance cursor signing key. crypto/rand is not
// expected to fail; the counter fallback still keeps keys unique per
// instance so cursors never validate across indexes.
func newKey() [32]byte {
	var key [32]byte
	if _, err := rand.Read(key[:]); err != nil {
		binary.BigEndian.PutUint64(key[:8], keyFallback.Add(1))
	}
	return key
}

# 链上索引与交易分析服务

## 用途

区块与交易摄取（含可选区块时间）、事件解码与规范化、可组合查询与按时间窗口分段的交易聚合、索引重建与一致性校验、分析指标与快照。

本仓库是可持续演进的自托管 Go 应用。领域核心位于 `indexroom/`，命令入口位于 `cmd/indexroom/`。

```bash
go run ./cmd/indexroom demo
go run ./cmd/indexroom version
go test ./...
```

## 主要接口

- `indexroom.Block` 的 `Time *int64` 字段携带非负 Unix 秒数；`nil` 表示未提供时间，与时间为 0 严格区分。
- `Index.Append` / `Index.Reorg`：摄取区块与重组，负时间整体拒绝且不改变已有链；哈希、父哈希或任一交易标识含非法 UTF-8 字节时同样整体拒绝，错误信息指出区块高度与字段（交易标识另指出从 0 开始的位置），保证快照可无损导出与恢复。`Append` 在链顶前进后仍可再次提交内容完全相同的旧区块（成功且无副作用），完整规则见下方[重复提交区块指南（Append）](#重复提交区块指南append)；`Reorg` 的分支范围、丢弃高度口径、失败原子性与完整用法见下方[重组指南（Reorg）](#重组指南reorg)。
- `Index.QueryTxs`：既有分页交易查询，围绕一个或多个交易标识读取主链上的每次出现；默认按高度、再按块内位置升序返回，`Order` 设为 `OrderDesc` 时整体倒序（高度与块内位置均从大到小）；`TimeStart`/`TimeEnd` 可同时给出非负 Unix 秒，叠加 `[Start, End)` 半开时间窗口筛选（含起点、排除终点，与 `QueryTimeStats` 一致；缺失区块时间不命中，真实零秒按窗口判断），两者都不传表示不启用时间筛选；固定高度范围内的区块时间变化会使旧游标返回 `ErrQueryChanged`。完整翻页用法见下方[分页交易查询指南](#分页交易查询指南querytxs)。
- `Index.QueryTimeStats`：按 `[Start, End)` 半开窗口与 `StepSeconds` 分段统计交易出现次数、不同标识数、含匹配交易的区块数，并给出整窗口去重汇总与缺失时间区块数；非法参数返回 `ErrInvalidArgument`。完整用法见下方[按时间窗口统计交易指南](#按时间窗口统计交易指南querytimestats)。
- `Index.Export` / `Index.Restore`：快照版本 1（区块不含 `timestamp`）与版本 2（任一块有时间时为每块输出必填 `timestamp`，缺失为 `null`）。`Restore` 保证**数据一致**并把再导出规范化为本功能的固定文本，不保留输入的字段顺序、空白与转义写法；它用一份完整快照整体替换主链，非法输入返回 `ErrInvalidSnapshot` 且不改变现有链；底层读取失败（包括与完整快照字节一起送达的故障）不是 `ErrInvalidSnapshot`，而是包装为 `indexroom: read snapshot: ...` 并保留原始读取错误，同样不改变现有链。完整用法见下方[快照导出与恢复指南（Export/Restore）](#快照导出与恢复指南exportrestore)。

## 分页交易查询指南（QueryTxs）

`Index.QueryTxs(query TxQuery) (TxPage, error)` 围绕一个或多个交易标识读取这些标识在主链上的**每一次出现**。默认按"高度、再按块内位置"升序；`Order` 设为 `OrderDesc` 时在整个固定范围内倒序——高度从大到小，同一区块内的位置也从大到小。次序只由高度与原有块内位置决定，区块时间是否缺失、相同或随高度下降都不影响次序。查询只读，可与摄取并发调用，每次调用都看到一个完整的链状态。

- `TxQuery`：`From`/`To` 为闭区间高度，`TxIDs` 为筛选标识集合，`PageSize` 为每页条数（0 取 `DefaultPageSize=100`，最大 `MaxPageSize=1000`），`Order` 为读取方向（零值 `OrderAsc` 升序，`OrderDesc` 倒序），`TimeStart`/`TimeEnd` 为可选时间窗口（两个 `*int64`，同时给出才启用，半开 `[Start, End)`，单位为非负 Unix 秒），`Cursor` 为续查游标。
- `TxHit`：一次命中，字段为 `Height`、`BlockHash`、`TxID`、`Position`（块内从 0 开始的位置；**倒序不会重新编号**）。
- `TxPage`：本页 `Hits`，以及对整个固定范围的统计 `TotalMatches`（匹配出现总次数）、`MatchedBlocks`（含匹配交易的区块数）、`ToHeight`（第一页固定下来的实际上界）和 `NextCursor`。统计是整个固定范围的统计，**不随方向或页大小改变**。

### 如何取得第一页、继续读取、何时结束

1. **第一页**：`Cursor` 传空字符串即首次查询。`From` 为 0 时默认从高度 1 开始；`To` 为 0 时取首次查询看到的链顶。需要先看靠近链顶的记录时，把 `Order` 设为 `OrderDesc`（见下方[倒序读取](#倒序读取orderdesc)）。
2. **继续读取**：把上一页返回的 `NextCursor` 原样填回 `TxQuery.Cursor` 再次调用。游标是服务返回的**不透明字符串**，不要解析或拼接。续查时高度范围、`TxIDs`、读取方向 `Order` 以及是否启用时间窗口和窗口本身必须与第一页等价或一致；`PageSize` 可以逐页调整。
3. **结束**：返回页的 `NextCursor` 为空即最后一页。范围内没有匹配交易时不是错误，而是成功返回一个空页（`Hits` 为空、无游标）。

重复出现的交易**不会合并**：同一标识在不同区块、或同一区块内出现多次，就返回多条 `TxHit`。筛选按字符串精确匹配，`TxIDs` 的**顺序与重复项不影响匹配**（`["a","a"]` 与 `["a"]` 等价）；但大小写与首尾空白仍按原字符串区分（`"A"`、`" a "` 都不会匹配 `"a"`）。

### 范围在第一页固定

- 第一页若显式给出高于当前链顶的 `To`，返回的 `ToHeight` 是夹到链顶后的值；**后续请求仍要传原先请求的 `To`，不能用返回值替换**（例如首查 `To=10`、链顶只有 3 时 `ToHeight=3`，续查仍须传 `To=10`）。
- 范围固定后，之后新追加的区块对本次翻页不可见：第一页之后再追加含匹配标识的区块，继续翻页仍只读取原来固定的范围，`TotalMatches`、`MatchedBlocks` 也不增加。需要新数据就以空游标重新开始一次查询。

### 游标失效：区分 ErrQueryChanged 与 ErrInvalidArgument

- **`ErrQueryChanged`（链数据变了）**：固定范围内任一区块的内容发生改变——即使区块哈希不变、**只改变了时间**——或链顶退到固定结束高度以下，续查都会返回该错误，且**没有可用的页结果**。此时只能**从空游标重新开始第一页**，绝不能把新结果拼接到旧结果后面。
- **`ErrInvalidArgument`（请求本身不合法）**：续查更改高度范围或筛选集合、**续查方向与游标不一致**（正序游标配 `OrderDesc`，或倒序游标配 `OrderAsc`/不传 `Order`）、**续查改变时间筛选的启用状态或窗口任一边界**、只给时间窗口一个边界、时间边界为负、起点不小于终点、传入非法 `Order` 值、游标损坏、或把游标交给另一个索引实例（游标带实例签名，跨实例无效）。它与链数据变化无关，用 `errors.Is` 与 `ErrQueryChanged` 区分；请先修正请求再重试。方向或窗口不一致的续查同样**不返回任何可用页结果**。

### 倒序读取（OrderDesc）

- **选择倒序**：第一页把 `TxQuery.Order` 设为 `indexroom.OrderDesc`。不设置（零值 `OrderAsc`）时行为与过去完全一致，原有正序调用与有效游标都不受影响。
- **整体次序**：倒序作用于**整个固定范围**，不是只翻转当前页。命中按高度从大到小返回，同一区块内的 `Position` 也从大到小；逐页拼接后仍符合这一整体次序。每条命中的 `Position` 仍是它在区块内从 0 开始的真实位置，**不会因为倒序重新编号**；同一标识的每次出现也**不会合并**。
- **继续翻页**：续查必须沿用第一页的读取方向，继续把 `NextCursor` 原样传回；`PageSize` 仍可逐页调整，未读记录既不重复也不遗漏。
- **切换方向**：不能拿一个方向的游标去续查另一个方向——会得到 `ErrInvalidArgument`。要改读另一方向，**以空游标重新发起一次第一页查询**（此时会按当时的链顶重新固定范围）。
- **范围固定与统计**：第一页照旧固定实际上界，随后追加的更高区块不能插进进行中的倒序翻页；要读取这些新记录同样需要空游标重查。`TotalMatches`、`MatchedBlocks`、`ToHeight` 仍是整个固定范围的统计，与方向、页大小无关。
- **空结果**：空链、起始高度超过链顶、或筛选无命中时，倒序也成功返回空页与空的后续游标。

例如高度 1 至 3 的交易依次是 `[a,b,a]`、`[a,c]`、`[b,a]`，筛选 `a`、每页 2 条时：第一页依次给出**高度 3 位置 1、高度 2 位置 0**，第二页依次给出**高度 1 位置 2、高度 1 位置 0**，随后结束翻页；两页的 `TotalMatches` 都是 4、`MatchedBlocks` 都是 3。

### 时间窗口筛选（TimeStart/TimeEnd）

- **启用方式**：`TxQuery.TimeStart` 与 `TxQuery.TimeEnd` 同时给出非 `nil` 的 `*int64`，即按**半开窗口 `[Start, End)`** 筛选区块时间（非负 Unix 秒，**包含起点、排除终点**），语义与 `QueryTimeStats` 一致。两个字段都不传（均为 `nil`）时**不启用**时间筛选，行为与过去完全一致，原有调用与有效游标不受影响。
- **未启用与起点为零是两回事**：调用方必须能区分"没有时间筛选"（两个指针都为 `nil`）与"窗口起点恰好为零"（`TimeStart` 指向 0、`TimeEnd` 指向更大的值）。只给一个边界（只给起点或只给终点）是 `ErrInvalidArgument`。
- **缺失时间不命中，真实零秒按窗口判断**：启用窗口后，`Time` 为 `nil`（没有时间）的区块**永不命中**；时间为 0 是真实时间戳，按数值与窗口比较（例如窗口 `[0,1)` 会保留它）。这与摄取、快照中"缺失时间不是 0"的区分一致。
- **三类条件共同生效**：一次出现必须**同时**落在高度范围、时间窗口内、且标识通过 `TxIDs` 筛选才被保留。时间窗口只决定哪些出现被保留，**不改变读取次序**——结果仍按高度与原有块内位置正序或倒序读取，不能改成按时间排序；同一标识的重复出现既**不合并也不重新编号**，`Position` 仍是块内从 0 开始的真实位置。时间允许随高度下降、允许相等，均按实际值判断。
- **统计口径**：`TotalMatches` 与 `MatchedBlocks` 描述**固定高度范围内通过全部条件**（标识 + 时间窗口）的出现次数与区块数，每页保持一致；`ToHeight` 仍表示第一页固定下来的高度上界，与是否启用窗口无关。合法窗口没有命中时不是错误：成功返回空页（`Hits` 为空、无后续游标）。
- **参数错误**：只提供一个边界、起点或终点为负、起点不小于终点，都返回 `ErrInvalidArgument` 且**不提供可用页**。
- **继续翻页沿用同一窗口**：续查必须沿用"是否启用时间筛选"及完全相同的窗口；在启用与不启用之间切换、或改变任一边界，都返回 `ErrInvalidArgument` 且没有可用页，调用方需**从空游标重新查询**。`PageSize` 仍可逐页调整。
- **范围变化判定不变**：固定范围内**任一**区块内容变化（包括原本因时间不在窗口内而未命中的区块、缺失时间变成已知时间等）续查仍返回 `ErrQueryChanged` 且没有可用页，必须从空游标重新开始，不能把新结果接到旧结果后面。

例如高度一至四的时间依次为 105、缺失、100、110，交易依次为 `[a,b,a]`、`[a]`、`[a]`、`[a]`。筛选 `a` 与窗口 `[100,110)`、正序每页两条时：第一页返回**高度一的位置零和位置二**（时间 105 在窗口内；同一区块两次出现都保留），第二页返回**高度三的位置零**（时间 100 在窗口内）；高度二缺失时间不命中、高度四时间 110 正好等于被排除的终点。总出现次数 `TotalMatches=3`、匹配区块数 `MatchedBlocks=2`，高度上界 `ToHeight` 仍为 4。

### 完整示例

下面的程序只使用现有公开功能，在本机离线即可运行，源码位于 [`examples/querytxs/main.go`](examples/querytxs/main.go)：

```bash
go run ./examples/querytxs
```

场景：三个连续区块的交易列表依次为 `[a,b,a]`、`[a]`、`[b]`，筛选标识 `a`，每页 2 条。第一页返回高度 1 中的两次 `a`（位置 0、2），第二页返回高度 2 中的一次 `a`（位置 0）；两页的 `TotalMatches` 都是 3、`MatchedBlocks` 都是 2，最后一页没有后续游标。

```go
// 分页交易查询（Index.QueryTxs）完整示例：第一页、继续翻页、范围固定、
// 筛选语义、空页、倒序读取、时间窗口筛选、ErrInvalidArgument 与
// ErrQueryChanged 的处理。
//
// 运行：go run ./examples/querytxs
package main

import (
	"errors"
	"fmt"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func mustAppend(index *indexroom.Index, block indexroom.Block) {
	if err := index.Append(block); err != nil {
		panic(err)
	}
}

// unix 返回指向给定 Unix 秒的指针，用于设置区块时间或时间窗口边界。
func unix(sec int64) *int64 { return &sec }

func printPage(title string, page indexroom.TxPage) {
	fmt.Println(title + "：")
	for _, hit := range page.Hits {
		fmt.Printf("  命中 height=%d block=%s tx=%q position=%d\n",
			hit.Height, hit.BlockHash, hit.TxID, hit.Position)
	}
	fmt.Printf("  TotalMatches=%d MatchedBlocks=%d ToHeight=%d 有后续游标=%v\n",
		page.TotalMatches, page.MatchedBlocks, page.ToHeight, page.NextCursor != "")
}

func main() {
	// 三个连续区块，交易列表依次为 [a,b,a]、[a]、[b]。
	index := indexroom.New()
	mustAppend(index, indexroom.Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"a", "b", "a"}})
	mustAppend(index, indexroom.Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}})
	mustAppend(index, indexroom.Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"b"}})
	fmt.Printf("链顶高度 tip=%d\n\n", index.Tip)

	// 取得第一页：Cursor 留空表示首次查询，From 留空默认从高度 1 开始。
	// 显式 To=10 高于当前链顶 3，第一页把查询范围固定到实际链顶 3。
	query := indexroom.TxQuery{To: 10, TxIDs: []string{"a"}, PageSize: 2}
	page1, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("第1页（请求 To=10，链顶只有 3）", page1)

	// 翻页时每页条数可以调整，其余条件必须与首次查询等价。
	sized := indexroom.TxQuery{To: 10, TxIDs: []string{"a"}, PageSize: 1}
	sizedPage1, err := index.QueryTxs(sized)
	if err != nil {
		panic(err)
	}
	printPage("同一范围每页 1 条时的第1页", sizedPage1)
	sized.Cursor = sizedPage1.NextCursor
	sized.PageSize = 3 // 下一页改成每页 3 条
	sizedPage2, err := index.QueryTxs(sized)
	if err != nil {
		panic(err)
	}
	printPage("改为每页 3 条后继续", sizedPage2)

	// 第一页之后链上又追加一个含 a 的高度 4 区块。
	mustAppend(index, indexroom.Block{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"a"}})
	fmt.Printf("已追加高度 4，当前链顶 tip=%d\n\n", index.Tip)

	// 继续读取：沿用服务返回的不透明游标，To 仍传最初请求的 10，
	// 不能用第一页返回的 ToHeight=3 替换，否则属于另一次查询。
	query.Cursor = page1.NextCursor
	page2, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("第2页（追加高度 4 之后继续翻页）", page2)
	fmt.Printf("最后一页没有后续游标：%v\n\n", page2.NextCursor == "")

	// 重复出现的交易不会合并；筛选标识的顺序与重复项不影响匹配；
	// 大小写与首尾空白仍按原字符串做精确区分。
	dupA, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, TxIDs: []string{"a", "a"}})
	if err != nil {
		panic(err)
	}
	setAB1, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, TxIDs: []string{"a", "b"}})
	if err != nil {
		panic(err)
	}
	setAB2, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, TxIDs: []string{"b", "a", "b"}})
	if err != nil {
		panic(err)
	}
	fmt.Printf("筛选 [a,a] 命中 %d 条；[a,b] 命中 %d 条，乱序且重复的 [b,a,b] 同样命中 %d 条\n",
		dupA.TotalMatches, setAB1.TotalMatches, setAB2.TotalMatches)
	upper, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, TxIDs: []string{"A"}})
	if err != nil {
		panic(err)
	}
	spaced, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, TxIDs: []string{" a "}})
	if err != nil {
		panic(err)
	}
	fmt.Printf("筛选 %q 命中 %d 条，筛选 %q 命中 %d 条（都是成功的空页）\n\n",
		"A", len(upper.Hits), " a ", len(spaced.Hits))

	// To=0 表示取首次查询看到的链顶；范围内没有匹配交易时成功返回空页。
	tipBound, err := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"a"}, PageSize: 10})
	if err != nil {
		panic(err)
	}
	fmt.Printf("To=0 固定到首次查询看到的链顶：ToHeight=%d（当前 tip=%d）\n",
		tipBound.ToHeight, index.Tip)
	empty, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 3, TxIDs: []string{"zzz"}})
	if err != nil {
		panic(err)
	}
	fmt.Printf("无匹配交易：err=%v 命中 %d 条 有后续游标=%v\n\n",
		err, len(empty.Hits), empty.NextCursor != "")

	// 参数类错误（ErrInvalidArgument）：与链数据变化无关。
	fresh, err := index.QueryTxs(indexroom.TxQuery{To: 3, TxIDs: []string{"a"}, PageSize: 2})
	if err != nil {
		panic(err)
	}
	goodCursor := fresh.NextCursor // 不透明字符串，只应原样传回
	continueWith := func(to int64, from int64, txIDs []string, cursor string) error {
		_, err := index.QueryTxs(indexroom.TxQuery{From: from, To: to, TxIDs: txIDs, PageSize: 2, Cursor: cursor})
		return err
	}
	fmt.Printf("续查更改结束高度：ErrInvalidArgument=%v\n",
		errors.Is(continueWith(10, 0, []string{"a"}, goodCursor), indexroom.ErrInvalidArgument))
	fmt.Printf("续查更改起始高度：ErrInvalidArgument=%v\n",
		errors.Is(continueWith(3, 2, []string{"a"}, goodCursor), indexroom.ErrInvalidArgument))
	fmt.Printf("续查更改筛选集合：ErrInvalidArgument=%v\n",
		errors.Is(continueWith(3, 0, []string{"b"}, goodCursor), indexroom.ErrInvalidArgument))
	fmt.Printf("游标损坏：ErrInvalidArgument=%v\n",
		errors.Is(continueWith(3, 0, []string{"a"}, "q1.damaged"), indexroom.ErrInvalidArgument))
	other := indexroom.New()
	_, err = other.QueryTxs(indexroom.TxQuery{To: 3, TxIDs: []string{"a"}, PageSize: 2, Cursor: goodCursor})
	fmt.Printf("游标交给另一个索引实例：ErrInvalidArgument=%v\n\n",
		errors.Is(err, indexroom.ErrInvalidArgument))

	// 固定范围内任一区块内容改变（即使只改时间）：续查返回 ErrQueryChanged，
	// 且没有可用的页结果。分支必须覆盖受影响高度之后的所有区块。
	changedTime := int64(1700000000)
	dropped, err := index.Reorg([]indexroom.Block{
		{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}, Time: &changedTime},
		{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"b"}},
		{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"a"}},
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("只改高度 2 的时间，重组替换高度 %v，当前 tip=%d\n", dropped, index.Tip)
	changedPage, err := index.QueryTxs(indexroom.TxQuery{To: 3, TxIDs: []string{"a"}, PageSize: 2, Cursor: goodCursor})
	fmt.Printf("续查：ErrQueryChanged=%v ErrInvalidArgument=%v 可用命中数=%d\n",
		errors.Is(err, indexroom.ErrQueryChanged),
		errors.Is(err, indexroom.ErrInvalidArgument), len(changedPage.Hits))
	// 正确做法：从空游标重新开始，不能把新结果接到旧结果后面。
	restart, err := index.QueryTxs(indexroom.TxQuery{To: 3, TxIDs: []string{"a"}, PageSize: 2})
	if err != nil {
		panic(err)
	}
	printPage("从空游标重新开始后的第1页", restart)

	// 链顶退到固定结束高度以下，同样是 ErrQueryChanged。
	pinned, err := index.QueryTxs(indexroom.TxQuery{To: 10, TxIDs: []string{"a"}, PageSize: 2})
	if err != nil {
		panic(err)
	}
	dropped, err = index.Reorg([]indexroom.Block{{Height: 2, Hash: "h2c", Parent: "h1", Txs: []string{"a"}}})
	if err != nil {
		panic(err)
	}
	fmt.Printf("链顶回退，重组丢弃高度 %v，当前 tip=%d\n", dropped, index.Tip)
	_, err = index.QueryTxs(indexroom.TxQuery{To: 10, TxIDs: []string{"a"}, PageSize: 2, Cursor: pinned.NextCursor})
	fmt.Printf("续查：ErrQueryChanged=%v（固定结束高度为 %d）\n",
		errors.Is(err, indexroom.ErrQueryChanged), pinned.ToHeight)
	restartTip, err := index.QueryTxs(indexroom.TxQuery{To: 10, TxIDs: []string{"a"}, PageSize: 10})
	if err != nil {
		panic(err)
	}
	printPage("再次从空游标重新开始", restartTip)

	demonstrateDescending()
	demonstrateTimeWindow()
}

// demonstrateTimeWindow 在独立索引上展示可选区块时间窗口：时间筛选与高度范围、
// 交易标识筛选共同生效；次序仍由高度与块内位置决定；缺失时间不命中、真实零秒
// 按窗口判断；续查必须沿用同一窗口，改变启用状态或任一边界都是
// ErrInvalidArgument；固定范围内原本因时间未命中的区块变化仍是 ErrQueryChanged。
func demonstrateTimeWindow() {
	fmt.Println("---- 时间窗口筛选（TimeStart/TimeEnd: [Start, End)）----")
	// 规格示例：高度 1 至 4 的时间依次为 105、缺失、100、110，交易依次为
	// [a,b,a]、[a]、[a]、[a]。
	index := indexroom.New()
	mustAppend(index, indexroom.Block{Height: 1, Hash: "w1", Parent: "genesis", Txs: []string{"a", "b", "a"}, Time: unix(105)})
	mustAppend(index, indexroom.Block{Height: 2, Hash: "w2", Parent: "w1", Txs: []string{"a"}})
	mustAppend(index, indexroom.Block{Height: 3, Hash: "w3", Parent: "w2", Txs: []string{"a"}, Time: unix(100)})
	mustAppend(index, indexroom.Block{Height: 4, Hash: "w4", Parent: "w3", Txs: []string{"a"}, Time: unix(110)})

	// 启用窗口：TimeStart 与 TimeEnd 同时给出，含起点、排除终点 [100,110)。
	// 高度 2 没有时间不命中；高度 4 时间正好等于终点 110 被排除。
	// 两个字段都留 nil 表示不启用筛选，这与起点恰好为零的窗口不同。
	query := indexroom.TxQuery{
		TxIDs: []string{"a"}, TimeStart: unix(100), TimeEnd: unix(110), PageSize: 2,
	}
	page1, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("窗口 [100,110) 筛选 a，每页 2 条：第1页", page1)

	// 继续翻页：是否启用窗口及窗口本身必须与第一页一致；PageSize 仍可调整。
	query.Cursor = page1.NextCursor
	query.PageSize = 10
	page2, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("同窗口继续（本页改每页 10 条）", page2)
	fmt.Println("  两页 TotalMatches 都是 3（高度1两次、高度3一次）、MatchedBlocks 都是 2、ToHeight 仍是 4")
	fmt.Println("  次序只按高度与块内位置：高度1时间105 仍排在高度3时间100 之前，没有改成按时间排序")
	fmt.Println()

	// 真实零秒是有效时间，缺失时间不是：窗口 [0,1) 只保留高度 1 那块
	// 真实时间为零的区块。
	zeroIndex := indexroom.New()
	mustAppend(zeroIndex, indexroom.Block{Height: 1, Hash: "z1", Parent: "genesis", Txs: []string{"a"}, Time: unix(0)})
	mustAppend(zeroIndex, indexroom.Block{Height: 2, Hash: "z2", Parent: "z1", Txs: []string{"a"}})
	zeroWin, err := zeroIndex.QueryTxs(indexroom.TxQuery{TimeStart: unix(0), TimeEnd: unix(1)})
	if err != nil {
		panic(err)
	}
	fmt.Printf("窗口 [0,1)：命中 %d 条（真实零秒命中，缺失时间不命中）；", zeroWin.TotalMatches)
	disabled, err := zeroIndex.QueryTxs(indexroom.TxQuery{})
	if err != nil {
		panic(err)
	}
	fmt.Printf("不启用窗口命中 %d 条（缺失时间也保留）\n", disabled.TotalMatches)

	// 合法窗口没有命中时仍是成功的空页，没有后续游标。
	empty, err := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"a"}, TimeStart: unix(1000), TimeEnd: unix(2000)})
	if err != nil {
		panic(err)
	}
	fmt.Printf("窗口 [1000,2000) 无命中：err=%v 命中=%d 有后续游标=%v\n\n",
		err, len(empty.Hits), empty.NextCursor != "")

	// 非法窗口：只给一个边界、边界为负、起点不小于终点，都是
	// ErrInvalidArgument，且没有可用页结果。
	invalid := []struct {
		name  string
		query indexroom.TxQuery
	}{
		{"只给起点", indexroom.TxQuery{TimeStart: unix(100)}},
		{"只给终点", indexroom.TxQuery{TimeEnd: unix(110)}},
		{"负起点", indexroom.TxQuery{TimeStart: unix(-1), TimeEnd: unix(110)}},
		{"负终点", indexroom.TxQuery{TimeStart: unix(0), TimeEnd: unix(-1)}},
		{"起点不小于终点", indexroom.TxQuery{TimeStart: unix(110), TimeEnd: unix(110)}},
	}
	for _, tc := range invalid {
		page, err := index.QueryTxs(tc.query)
		fmt.Printf("%s：ErrInvalidArgument=%v 可用命中数=%d\n",
			tc.name, errors.Is(err, indexroom.ErrInvalidArgument), len(page.Hits))
	}
	fmt.Println()

	// 续查改变窗口（含从启用改为不启用）返回 ErrInvalidArgument，没有可用页；
	// 要改窗口必须从空游标重新查询。
	first, err := index.QueryTxs(indexroom.TxQuery{
		TxIDs: []string{"a"}, TimeStart: unix(100), TimeEnd: unix(110), PageSize: 1,
	})
	if err != nil {
		panic(err)
	}
	changedEnd, err := index.QueryTxs(indexroom.TxQuery{
		TxIDs: []string{"a"}, TimeStart: unix(100), TimeEnd: unix(111),
		PageSize: 1, Cursor: first.NextCursor,
	})
	fmt.Printf("续查改终点：ErrInvalidArgument=%v 可用命中数=%d\n",
		errors.Is(err, indexroom.ErrInvalidArgument), len(changedEnd.Hits))
	disabledCont, err := index.QueryTxs(indexroom.TxQuery{
		TxIDs: []string{"a"}, PageSize: 1, Cursor: first.NextCursor,
	})
	fmt.Printf("续查去掉窗口：ErrInvalidArgument=%v 可用命中数=%d\n",
		errors.Is(err, indexroom.ErrInvalidArgument), len(disabledCont.Hits))

	// 固定范围内任一区块内容变化，包括原本因时间而未命中的区块（这里给
	// 缺失时间的高度 2 补上窗口外时间 120），续查仍是 ErrQueryChanged。
	if _, err := index.Reorg([]indexroom.Block{
		{Height: 2, Hash: "w2", Parent: "w1", Txs: []string{"a"}, Time: unix(120)},
		{Height: 3, Hash: "w3", Parent: "w2", Txs: []string{"a"}, Time: unix(100)},
		{Height: 4, Hash: "w4", Parent: "w3", Txs: []string{"a"}, Time: unix(110)},
	}); err != nil {
		panic(err)
	}
	changedPage, err := index.QueryTxs(indexroom.TxQuery{
		TxIDs: []string{"a"}, TimeStart: unix(100), TimeEnd: unix(110),
		PageSize: 1, Cursor: first.NextCursor,
	})
	fmt.Printf("原本未命中的高度2内容变化：ErrQueryChanged=%v 可用命中数=%d\n",
		errors.Is(err, indexroom.ErrQueryChanged), len(changedPage.Hits))
}

// demonstrateDescending 在独立索引上展示倒序读取：如何选择倒序、跨页继续、
// 范围在第一页固定、方向混用被拒绝，以及切换方向时需要重新发起查询。
func demonstrateDescending() {
	fmt.Println("---- 倒序读取（Order: indexroom.OrderDesc）----")
	// 规格示例：高度 1 至 3 的交易依次是 [a,b,a]、[a,c]、[b,a]，筛选 a。
	index := indexroom.New()
	mustAppend(index, indexroom.Block{Height: 1, Hash: "g1", Parent: "genesis", Txs: []string{"a", "b", "a"}})
	mustAppend(index, indexroom.Block{Height: 2, Hash: "g2", Parent: "g1", Txs: []string{"a", "c"}})
	mustAppend(index, indexroom.Block{Height: 3, Hash: "g3", Parent: "g2", Txs: []string{"b", "a"}})

	// 选择倒序：TxQuery.Order 传 indexroom.OrderDesc；不传（零值）仍是正序。
	query := indexroom.TxQuery{From: 1, To: 3, TxIDs: []string{"a"}, PageSize: 2, Order: indexroom.OrderDesc}
	page1, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("倒序第1页（从靠近链顶的出现开始）", page1)

	// 继续翻页：Order 必须沿用第一页的倒序，PageSize 仍可调整，游标原样传回。
	query.Cursor = page1.NextCursor
	page2, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	printPage("倒序第2页（继续向低高度读取，随后结束翻页）", page2)

	// 第一页固定实际上界：之后追加的更高区块不能插进正在进行的倒序翻页。
	mustAppend(index, indexroom.Block{Height: 4, Hash: "g4", Parent: "g3", Txs: []string{"a"}})
	fmt.Printf("已追加高度 4，当前链顶 tip=%d\n", index.Tip)
	query.Cursor = page1.NextCursor
	replayed, err := index.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	fmt.Printf("倒序续查仍只看固定范围 1..3：本页 %d 条、ToHeight=%d、TotalMatches=%d\n\n",
		len(replayed.Hits), replayed.ToHeight, replayed.TotalMatches)

	// 要读取新记录，以空游标重新查询；想换方向也一样，必须重新发起第一页。
	freshDesc, err := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"a"}, PageSize: 2, Order: indexroom.OrderDesc})
	if err != nil {
		panic(err)
	}
	printPage("空游标重新倒序查询（第一页固定到新链顶 4）", freshDesc)

	// 方向必须与游标一致：拿正序游标请求倒序、或拿倒序游标请求正序，
	// 都返回 ErrInvalidArgument，且没有可用页结果。
	asc, err := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"a"}, PageSize: 2})
	if err != nil {
		panic(err)
	}
	desc, err := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"a"}, PageSize: 2, Order: indexroom.OrderDesc})
	if err != nil {
		panic(err)
	}
	wrong1, err1 := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"a"}, PageSize: 2, Order: indexroom.OrderDesc, Cursor: asc.NextCursor})
	wrong2, err2 := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"a"}, PageSize: 2, Cursor: desc.NextCursor})
	fmt.Printf("正序游标配倒序请求：ErrInvalidArgument=%v 可用命中数=%d\n",
		errors.Is(err1, indexroom.ErrInvalidArgument), len(wrong1.Hits))
	fmt.Printf("倒序游标配正序请求：ErrInvalidArgument=%v 可用命中数=%d\n\n",
		errors.Is(err2, indexroom.ErrInvalidArgument), len(wrong2.Hits))

	// 空链、起始高度超过链顶、筛选无命中：倒序同样成功返回空页与空游标。
	empty := indexroom.New()
	emptyPage, err := empty.QueryTxs(indexroom.TxQuery{Order: indexroom.OrderDesc})
	if err != nil {
		panic(err)
	}
	noHit, err := index.QueryTxs(indexroom.TxQuery{TxIDs: []string{"zzz"}, Order: indexroom.OrderDesc})
	if err != nil {
		panic(err)
	}
	fmt.Printf("空链倒序：err=%v 命中=%d 游标为空=%v；筛选无命中倒序：命中=%d TotalMatches=%d\n",
		err, len(emptyPage.Hits), emptyPage.NextCursor == "", len(noHit.Hits), noHit.TotalMatches)
}
